import @vibe/compiler/runtime { db_new, db_set_source, db_typecheck_with_config }
import @vibe/compiler/config { target_cfg_from_csv }
import @vibe/compiler/syntax { print_program }
import @vibe/parser { set_cfg_ambient_flags }
import @vibe/compiler/linker/merge { merged_stmts_and_offsets }
test "retained target check owns its String lowering" {
  let path = "repro/main.vibe"
  let source = "#cfg(alpha)\nfn value() -> String { \"a\" }\n#cfg(beta)\nfn value() -> Int { 2 }\nfn chosen() -> Bool { let x = value(); let y = value(); let _ = x + y; x == y }\n"
  let cfg = target_cfg_from_csv("alpha")
  let db = db_set_source(db = db_new(), path = path, source = source)
  let checked = db_typecheck_with_config(db = db, path = path, cfg = cfg)

  let _ = db_typecheck_with_config(db = db, path = path, cfg = target_cfg_from_csv("beta"))
  let groups = [("repro", [(path, source)])]
  set_cfg_ambient_flags(["alpha"])
  let (stmts, _, _, _, _, _) = merged_stmts_and_offsets(groups)
  let has_concat = String::contains(print_program(stmts), needle = "String::concat")
  println("owned-repro\t\{has_concat}")
  assert(has_concat)
  set_cfg_ambient_flags([])
}

